// ---- Search Console weekly report: all numbers by code ----------------------------------------------
const nfkc = (s) => String(s ?? '').normalize('NFKC');
const iso = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const r1 = (x) => Math.round(x * 10) / 10;

// the two periods: the last full days that Search Console has (lag days back), and the same number of days before
function periods(todayIso, lagDays, days) {
  const t = new Date(todayIso + 'T00:00:00Z');
  const end = addDays(t, -lagDays);
  const start = addDays(end, -(days - 1));
  const pEnd = addDays(start, -1);
  const pStart = addDays(pEnd, -(days - 1));
  return { cur: { start: iso(start), end: iso(end) }, prev: { start: iso(pStart), end: iso(pEnd) } };
}

// the six API requests: totals, by query, by page, for each period
function requests(p) {
  const out = [];
  for (const period of ['cur', 'prev']) for (const dim of ['total', 'query', 'page']) {
    const body = { startDate: p[period].start, endDate: p[period].end, rowLimit: dim === 'total' ? 1 : 1000, dataState: 'final' };
    if (dim !== 'total') body.dimensions = [dim];
    out.push({ period, dim, body: JSON.stringify(body) });
  }
  return out;
}

const totalsOf = (rows) => {
  const r = rows?.[0];
  return r ? { clicks: r.clicks, impressions: r.impressions, ctr: r.ctr * 100, position: r.position } : { clicks: 0, impressions: 0, ctr: 0, position: null };
};
const mapOf = (rows) => new Map((rows ?? []).map((r) => [r.keys[0], r]));

// facts = a numbered list of statements with their numbers; the only things Claude may use
function buildFacts(res, cfg) {
  const min = Number(cfg.min_impressions) || 1, topN = Number(cfg.top_n) || 10;
  const facts = [];
  const add = (kind, label, values) => { const id = 'F' + (facts.length + 1); facts.push({ id, kind, label, values }); return id; };
  const c = totalsOf(res.cur.total), p = totalsOf(res.prev.total);
  const pct = (a, b) => (b > 0 ? r1(((a - b) / b) * 100) : null);
  add('total', 'clicks', { this_week: c.clicks, last_week: p.clicks, change: c.clicks - p.clicks, change_pct: pct(c.clicks, p.clicks) });
  add('total', 'impressions', { this_week: c.impressions, last_week: p.impressions, change: c.impressions - p.impressions, change_pct: pct(c.impressions, p.impressions) });
  add('total', 'ctr_percent', { this_week: r1(c.ctr), last_week: r1(p.ctr), change: r1(c.ctr - p.ctr) });
  add('total', 'average_position', { this_week: c.position === null ? null : r1(c.position), last_week: p.position === null ? null : r1(p.position),
    change: c.position !== null && p.position !== null ? r1(c.position - p.position) : null, note: 'lower is better' });

  // Google hides rare queries: say how many impressions have a known query, so a sum of queries is not read as the whole
  const known = (res.cur.query ?? []).reduce((a, r) => a + r.impressions, 0);
  add('total', 'impressions_with_a_known_query', { this_week: known, all_impressions: c.impressions, note: 'Search Console does not show every query' });
  for (const dim of ['query', 'page']) {
    const cur = mapOf(res.cur[dim]), prev = mapOf(res.prev[dim]);
    const top = [...cur.values()].filter((r) => r.impressions >= min).sort((a, b) => b.impressions - a.impressions || a.position - b.position).slice(0, topN);
    for (const r of top) {
      const q = prev.get(r.keys[0]);
      add('top_' + dim, r.keys[0], { impressions: r.impressions, clicks: r.clicks, position: r1(r.position),
        last_week_impressions: q ? q.impressions : 0, last_week_position: q ? r1(q.position) : null });
    }
    const fresh = [...cur.values()].filter((r) => !prev.has(r.keys[0]) && r.impressions >= min).sort((a, b) => b.impressions - a.impressions).slice(0, topN);
    for (const r of fresh) add('new_' + dim, r.keys[0], { impressions: r.impressions, clicks: r.clicks, position: r1(r.position) });
    const lost = [...prev.values()].filter((r) => !cur.has(r.keys[0]) && r.impressions >= min).sort((a, b) => b.impressions - a.impressions).slice(0, topN);
    for (const r of lost) add('lost_' + dim, r.keys[0], { last_week_impressions: r.impressions, last_week_position: r1(r.position) });
  }
  return facts;
}

// every number a fact contains, written the ways a sentence may write it (12, 12.0, 12.5, -3.2 -> 3.2)
function numbersOfFacts(facts) {
  const s = new Set();
  for (const f of facts) {
    for (const v of Object.values(f.values)) if (typeof v === 'number' && Number.isFinite(v)) {
      for (const x of [v, Math.abs(v)]) { s.add(String(x)); s.add(String(r1(x))); if (Number.isInteger(x)) s.add(x.toFixed(1)); }
    }
    for (const m of nfkc(f.label).match(/\d+(?:\.\d+)?/g) ?? []) s.add(m); // numbers that are part of a query or URL
  }
  return s;
}

// raw = Claude's text; returns the observations with a status each
function checkObservations(raw, facts) {
  let ai = null;
  try {
    const t = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const a = t.indexOf('{'), z = t.lastIndexOf('}');
    ai = JSON.parse(a >= 0 && z > a ? t.slice(a, z + 1) : t);
  } catch (e) { ai = null; }
  if (!ai) return { ok: false, problem: 'the AI output could not be read as JSON', items: [] };
  const byId = new Map(facts.map((f) => [f.id, f]));
  const items = (Array.isArray(ai.observations) ? ai.observations : []).slice(0, 6).map((o) => {
    const text = String(o?.text ?? '').trim();
    const ids = (Array.isArray(o?.fact_ids) ? o.fact_ids : []).map(String);
    const problems = [];
    if (!text) problems.push('empty');
    const unknown = ids.filter((id) => !byId.has(id));
    if (unknown.length) problems.push('unknown facts ' + unknown.join(', '));
    const used = ids.filter((id) => byId.has(id)).map((id) => byId.get(id));
    if (!used.length) problems.push('no fact referenced');
    // every number in the sentence must be a number of the facts it cites (thousands separators and % are ignored)
    const allowed = numbersOfFacts(used);
    const nums = nfkc(text).replace(/(?<=\d),(?=\d{3}(?!\d))/g, '').match(/\d+(?:\.\d+)?/g) ?? [];
    const bad = [...new Set(nums)].filter((n) => !allowed.has(n) && !allowed.has(String(Number(n))));
    if (bad.length) problems.push('numbers not in the cited facts: ' + bad.join(', '));
    // a quoted query or page must be one of the cited facts
    for (const q of text.match(/[「"“]([^」"”]+)[」"”]/g) ?? []) {
      const inner = q.slice(1, -1);
      if (inner.length > 2 && !used.some((f) => nfkc(f.label).toLowerCase().includes(nfkc(inner).toLowerCase()))) problems.push('quoted "' + inner + '" is not in the cited facts');
    }
    return { text, fact_ids: ids, ok: problems.length === 0, problems: problems.join('; ') };
  });
  return { ok: true, problem: '', items };
}

// the Slack text: the code's numbers first, then the observations with a mark
function report(p, facts, checked, site) {
  const f = (label) => facts.find((x) => x.kind === 'total' && x.label === label)?.values ?? {};
  const sign = (v) => (v === null || v === undefined ? '-' : (v > 0 ? '+' : '') + v);
  const cl = f('clicks'), im = f('impressions'), ct = f('ctr_percent'), po = f('average_position');
  const kq = f('impressions_with_a_known_query');
  const lines = [
    '*Search Console weekly* - ' + site + ' (' + p.cur.start + ' .. ' + p.cur.end + ' vs ' + p.prev.start + ' .. ' + p.prev.end + ')',
    'Clicks ' + cl.this_week + ' (' + sign(cl.change) + ')  |  Impressions ' + im.this_week + ' (' + sign(im.change) + ')  |  CTR ' + ct.this_week + '% (' + sign(ct.change) + ')  |  Avg position ' + (po.this_week ?? '-') + ' (' + sign(po.change) + ', lower is better)',
    '_Queries are known for ' + kq.this_week + ' of ' + kq.all_impressions + ' impressions (Search Console does not show every query)._',
  ];
  const list = (kind, title, fmt) => { const rows = facts.filter((x) => x.kind === kind); if (rows.length) lines.push('*' + title + '*\n' + rows.slice(0, 5).map(fmt).join('\n')); };
  list('top_query', 'Top queries', (x) => '• ' + x.label + ' - ' + x.values.impressions + ' impr, ' + x.values.clicks + ' clicks, pos ' + x.values.position);
  list('new_query', 'New queries', (x) => '• ' + x.label + ' - ' + x.values.impressions + ' impr, pos ' + x.values.position);
  list('lost_query', 'Queries gone', (x) => '• ' + x.label + ' - last week ' + x.values.last_week_impressions + ' impr');
  list('top_page', 'Top pages', (x) => '• ' + x.label + ' - ' + x.values.impressions + ' impr, ' + x.values.clicks + ' clicks');
  if (!checked.ok) lines.push(':warning: AI observations not available: ' + checked.problem);
  else if (checked.items.length) lines.push('*Observations (AI, checked by code)*\n' + checked.items.map((o) => (o.ok ? '✓ ' : ':warning: ') + o.text + (o.ok ? '' : '  _(' + o.problems + ')_')).join('\n'));
  return lines.join('\n');
}

